  function colourDefinitions(){return view==='form'?[['primary','Button & headings'],['primaryText','Button text'],['panel','Form panel'],['background','Page preview'],['input','Input background'],['text','Body text'],['muted','Muted text'],['border','Input border'],['error','Required & errors'],['soft','Field highlight'],['accent','Theme accent'],['sectionBackground','Section background'],['sectionText','Section heading'],['sectionBorder','Section divider'],['topBand','Top colour band']]:[['primary','Header'],['primaryText','Header text'],['accent','Accent'],['panel','Card background'],['background','Outer background'],['text','Body text'],['muted','Secondary text'],['border','Dividers'],['soft','Highlight panel']]}
